SELECT * FROM (SELECT e.event_id,'PLAN:'||s.plan_id case_id,e.activity,e.timestamp FROM (SELECT 'PLAN:'||plan_id||':submitted_at' event_id,'Rolling Plan Submitted' activity,submitted_at timestamp,plan_id source_key FROM planned_rolling_instruction WHERE submitted_at IS NOT NULL AND (1=1)) e JOIN planned_rolling_instruction s ON s.plan_id=e.source_key UNION ALL SELECT e.event_id,'PLAN:'||s.plan_id case_id,e.activity,e.timestamp FROM (SELECT 'PLAN:'||plan_id||':approved_at' event_id,'Rolling Plan Approved' activity,approved_at timestamp,plan_id source_key FROM planned_rolling_instruction WHERE approved_at IS NOT NULL AND (1=1)) e JOIN planned_rolling_instruction s ON s.plan_id=e.source_key UNION ALL SELECT e.event_id,'PLAN:'||s.plan_id case_id,e.activity,e.timestamp FROM (SELECT 'PLAN:'||plan_id||':released_at' event_id,'Rolling Plan Released' activity,released_at timestamp,plan_id source_key FROM planned_rolling_instruction WHERE released_at IS NOT NULL AND (1=1)) e JOIN planned_rolling_instruction s ON s.plan_id=e.source_key UNION ALL SELECT e.event_id,'PLAN:'||s.plan_id case_id,e.activity,e.timestamp FROM (SELECT 'INST:'||instruction_id event_id,'Rolling Instruction Issued' activity,issued_at timestamp,instruction_id source_key FROM rolling_instruction WHERE issued_at IS NOT NULL AND (1=1)) e JOIN rolling_instruction s ON s.instruction_id=e.source_key) ORDER BY case_id,timestamp,event_id;
